from multiprocessing import Pool, current_process
import time


def calculate_revenue(sale):
    """Calculate the revenue generated by one sales record."""
    product, quantity, unit_price = sale

    # Simulate work performed for each sales record.
    time.sleep(1)

    # Calculate the total revenue for this product.
    revenue = quantity * unit_price

    # Identify the process that handled the task.
    process_name = current_process().name

    print(
        f"Processed {product} using {process_name}"
    )

    # Return the product and its calculated revenue.
    return product, quantity, revenue


def main():
    # Each record contains a product, quantity sold, and unit price.
    sales = [
        ("Laptop", 5, 150000),
        ("Mouse", 20, 1500),
        ("Keyboard", 10, 3500),
        ("Monitor", 4, 45000),
        ("Headphones", 8, 5000),
        ("Printer", 3, 25000),
    ]

    print("Starting parallel sales processing...\n")

    # Create a pool of three worker processes.
    with Pool(processes=3) as pool:
        results = pool.map(calculate_revenue, sales)

    # Display the results after all tasks have completed.
    print("\nSales Revenue Report")
    print("-" * 65)

    total_revenue = 0

    for product, quantity, revenue in results:
        print(
            f"Product: {product:<12} "
            f"Quantity: {quantity:<3} "
            f"Revenue: Rs. {revenue:,.2f}"
        )

        total_revenue += revenue

    print("-" * 65)
    print(f"Total Revenue: Rs. {total_revenue:,.2f}")
    print("\nAll sales records processed successfully.")


# Required entry-point guard for multiprocessing programs.
if __name__ == "__main__":
    main()
